private function prepareToResolve($toResolve)
{
	if (!is_array($toResolve)) {
		return $toResolve;
	}
	$candidate = $toResolve;
	$class = array_shift($candidate);
	$method = array_shift($candidate);
	if (is_string($class) && is_string($method)) {
		return $class . ':' . $method;
	}
	return $toResolve;
}

